# 定义各工具参数 schema
class Tool_get_application_data(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
class Tool_ValidateApplicantIdentity(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    applicant_name: str = Field(..., description="Full legal name of the primary applicant")
    applicant_ssn: str = Field(..., description="Social Security Number in masked format ***-**-NNNN")
    applicant_dob: str = Field(..., description="Date of birth in ISO 8601 format YYYY-MM-DD")
    applicant_address: str = Field(..., description="Current residential address")
    co_applicant_name: Optional[str] = Field(None, description="Full legal name of co-applicant if applicable")
    co_applicant_ssn: Optional[str] = Field(None, description="Co-applicant SSN in masked format")

class Tool_ValidateEmploymentAndIncome(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    employment_status: str = Field(..., description="Employment classification")
    gross_monthly_income: float = Field(..., description="Self-declared gross monthly income")
    pay_stubs_uploaded: bool = Field(..., description="Confirmation of pay stubs upload")
    w2_forms_uploaded: bool = Field(..., description="Confirmation of W-2 forms upload")
    employer_name: Optional[str] = Field(None, description="Name of employer")
    employment_years: Optional[float] = Field(None, description="Years of employment")
    additional_income_monthly: Optional[float] = Field(None, description="Additional monthly income")
    tax_returns_uploaded: Optional[bool] = Field(None, description="Confirmation of tax returns upload")

class Tool_ValidateLiquidAssets(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    liquid_assets: float = Field(..., description="Total dollar amount of liquid assets")
    bank_statements_uploaded: bool = Field(..., description="Confirmation of bank statements upload")
    down_payment_amount: float = Field(..., description="Dollar amount of equity contribution")
    requested_loan_amount: float = Field(..., description="Dollar amount of mortgage financing requested")
    applicant_dob: str = Field(..., description="Date of birth in ISO 8601 format")
    retirement_accounts: Optional[float] = Field(None, description="Total dollar amount of retirement savings")

class Tool_PullCreditReports(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    verified_applicant_name: str = Field(..., description="Identity-verified full legal name")
    verified_applicant_ssn: str = Field(..., description="Identity-verified SSN in masked format")
    verified_applicant_dob: str = Field(..., description="Identity-verified date of birth")
    applicant_address: str = Field(..., description="Current residential address")
    credit_consent_signed: bool = Field(..., description="Credit consent confirmation")
    credit_consent_timestamp: str = Field(..., description="Credit consent timestamp")
    co_applicant_name: Optional[str] = Field(None, description="Co-applicant name if applicable")
    co_applicant_ssn: Optional[str] = Field(None, description="Co-applicant SSN if applicable")

class Tool_CalculateRepresentativeCreditScore(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    fico_score_equifax: Optional[int] = Field(None, description="FICO Score from Equifax")
    fico_score_experian: Optional[int] = Field(None, description="FICO Score from Experian")
    fico_score_transunion: Optional[int] = Field(None, description="FICO Score from TransUnion")
    co_applicant_fico_equifax: Optional[int] = Field(None, description="Co-applicant FICO from Equifax")
    co_applicant_fico_experian: Optional[int] = Field(None, description="Co-applicant FICO from Experian")
    co_applicant_fico_transunion: Optional[int] = Field(None, description="Co-applicant FICO from TransUnion")

class Tool_ExecutePrequalificationAnalysis(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    representative_credit_score: int = Field(..., description="Qualifying FICO score")
    preliminary_gross_monthly_income: float = Field(..., description="Preliminary validated gross monthly income")
    total_monthly_debt_obligations: float = Field(..., description="Sum of all recurring monthly debt payments")
    requested_loan_amount: float = Field(..., description="Dollar amount of mortgage financing requested")
    loan_term_months: int = Field(..., description="Number of months for loan amortization")
    estimated_property_value: float = Field(..., description="Estimated property market value")
    down_payment_amount: float = Field(..., description="Dollar amount of equity contribution")
    property_type: str = Field(..., description="Property structural classification")
    property_occupancy: str = Field(..., description="Intended occupancy status")
    loan_purpose: str = Field(..., description="Transaction type classification")

class Tool_VerifyEmploymentAndIncome(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
    prequalification_decision: str = Field(..., description="Pre-qualification classification outcome")
    employment_status: str = Field(..., description="Employment classification")
    gross_monthly_income: float = Field(..., description="Self-declared gross monthly income")
    pay_stubs_uploaded: bool = Field(..., description="Confirmation of pay stubs upload")
    w2_forms_uploaded: bool = Field(..., description="Confirmation of W-2 forms upload")
    employer_name: Optional[str] = Field(None, description="Name of employer")
    employment_years: Optional[float] = Field(None, description="Years of employment")
    additional_income_monthly: Optional[float] = Field(None, description="Additional monthly income")
    tax_returns_uploaded: Optional[bool] = Field(None, description="Confirmation of tax returns upload")

class Tool_VerifyAssetsAndReserves(BaseModel):
    application_id: str = Field(..., description="Unique identifier for the mortgage loan application")
