    down_payment_amount: float = Field(..., description="Dollar amount of equity contribution")
    requested_loan_amount: float = Field(..., description="Dollar amount of mortgage financing requested")
    applicant_dob: str = Field(..., description="Date of birth in ISO 8601 format")
